func sortedOrderMapKeys(m map[string]any) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		ki, kj := strings.TrimSpace(keys[i]), strings.TrimSpace(keys[j])
		pi := ki != "_key" && ki != "_term" && ki != "key"
		pj := kj != "_key" && kj != "_term" && kj != "key"
		if pi != pj {
			return pi
		}
		return ki < kj
	})
	return keys
}

func sortHistogramBuckets(buckets []map[string]any, order any) []map[string]any {
	type histSortSpec struct {
		target string
		desc   bool
	}
	var specs []histSortSpec
	parseMap := func(m map[string]any) {
		for _, k := range sortedOrderMapKeys(m) {
			v := m[k]
			if dir := extractCompositeSourceOrder(v); dir != "" {
				specs = append(specs, histSortSpec{
					target: strings.TrimSpace(k),
					desc:   strings.EqualFold(strings.TrimSpace(dir), "desc"),
				})
			}
		}
	}
	switch ov := order.(type) {
	case map[string]any:
		parseMap(ov)
	case []any:
		for _, item := range ov {
			if m, ok := item.(map[string]any); ok {
				parseMap(m)
			}
		}
	}
	if len(specs) == 0 || len(buckets) <= 1 {
		return buckets
	}
	sort.SliceStable(buckets, func(i, j int) bool {
		for _, sp := range specs {
			var vi, vj float64
			var okI, okJ bool
			switch sp.target {
			case "_key", "_term", "key":
				vi, okI = toFloat64(buckets[i]["key"])
				vj, okJ = toFloat64(buckets[j]["key"])
			case "_count", "doc_count":
				vi, okI = toFloat64(buckets[i]["doc_count"])
				vj, okJ = toFloat64(buckets[j]["doc_count"])
			default:
				vi, okI = extractBucketMetricByPath(buckets[i], sp.target)
				vj, okJ = extractBucketMetricByPath(buckets[j], sp.target)
			}
			if !okI && !okJ {
				continue
			}
			if !okI {
				return false
			}
			if !okJ {
				return true
			}
			if vi != vj {
				if sp.desc {
					return vi > vj
				}
				return vi < vj
			}
		}
		ki, _ := toFloat64(buckets[i]["key"])
		kj, _ := toFloat64(buckets[j]["key"])
		return ki < kj
	})
	return buckets
}

func (s *Server) isHighlightWeightMatchesDisabledR65(indexName string) bool {
	if s == nil || indexName == "" {
		return false
	}
	s.mu.RLock()
	defer s.mu.RUnlock()
	cs := s.indexCustomSettings[indexName]
	if cs == nil {
		return false
	}
	for _, k := range []string{"index.highlight.weight_matches_mode.enabled", "highlight.weight_matches_mode.enabled"} {
		if v, ok := cs[k]; ok && v != nil {
			if b, isB := v.(bool); isB {
				return !b
			}
			sVal := strings.ToLower(strings.TrimSpace(fmt.Sprintf("%v", v)))
			return sVal == "false" || sVal == "0" || sVal == "off" || sVal == "no"
		}
	}
	return false
}

